const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Jakarta Bay AOI - offshore region)
    const aoi = ee.Geometry.Polygon([
      [106.70, -5.95],
      [107.05, -5.95],
      [107.05, -6.20],
      [106.70, -6.20],
      [106.70, -5.95]
    ]);

    // 2. Data Acquisition & Check
    // JRC Yearly water classification for 2021 (fallback to 2020 if missing)
    function getYearlyImage(preferredYear, fallbackYear) {
      const col = ee.ImageCollection('JRC/GSW1_4/YearlyClassification');
      let colY = col.filter(ee.Filter.eq('year', preferredYear));
      let year = preferredYear;
      return ee.Dictionary(ee.Algorithms.If(
        colY.size().gt(0),
        ee.Dictionary({img: colY.first(), year: year}),
        ee.Dictionary(ee.Algorithms.If(
          ee.ImageCollection(col.filter(ee.Filter.eq('year', fallbackYear))).size().gt(0),
          {img: col.filter(ee.Filter.eq('year', fallbackYear)).first(), year: fallbackYear},
          {img: null, year: -1}
        ))
      ));
    }

    const yearInfo = getYearlyImage(2021, 2020);
    const usedYear = await yearInfo.get('year').getInfo();
    const yearlyImg = ee.Image(await yearInfo.get('img').getInfo() ? yearInfo.get('img') : null);

    if (usedYear === -1 || yearlyImg === null) {
      console.log('Yearly water classification images: 0');
      console.log('C1: Empty Collection (No images found in date/location)');
      console.log('C1');
      return;
    }

    // Determine band name robustly
    const yBandNames = await ee.Image(yearlyImg).bandNames().getInfo();
    let yBand = 'classification';
    if (!yBandNames || yBandNames.indexOf('classification') === -1) {
      if (yBandNames && yBandNames.length > 0) {
        yBand = yBandNames[0];
      } else {
        console.log('Band name detection failed for YearlyClassification.');
        console.log('D');
        return;
      }
    }

    // JRC baseline water occurrence (1984-2020); threshold for historical water
    const occurrence = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
    const baselineWater = occurrence.gte(50); // historically water (>=50% occurrence)

    // 3. Processing
    const yearClass = ee.Image(yearlyImg).select(yBand);
    // Not water in usedYear (class == 1). 0 is nodata, 2 water, 3 seasonal water.
    const notWaterYear = yearClass.eq(1).rename('nw');

    // New land (reclaimed/infilling): historically water AND not water in usedYear
    const newLandMask = notWaterYear.and(baselineWater).selfMask().clip(aoi);

    // Baseline water pixels in AOI (sanity check)
    const baseCount = await baselineWater.updateMask(baselineWater).clip(aoi)
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).get('occurrence').getInfo();

    if (baseCount === null || baseCount === 0) {
      console.log(`Using JRC yearly classification year: ${usedYear}`);
      console.log('Baseline water pixels in AOI (1km): 0');
      console.log('C2: No Valid Pixels (AOI lacks baseline water)');
      console.log('C2');
      return;
    }

    // New land pixel count (approx at 1km scale)
    const newLandCount = await newLandMask
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).get('nw').getInfo();

    // Area computation (ha) using pixelArea, coarse scale for performance
    const areaHa = await ee.Image.pixelArea().divide(10000).updateMask(newLandMask)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).get('area').getInfo();

    // 4. Validation & Final Answer
    if (areaHa === null || isNaN(areaHa)) {
      console.log(`Using JRC yearly classification year: ${usedYear}`);
      console.log(`Baseline water pixels in AOI (1km): ${baseCount}`);
      console.log(`New land pixels (1km): ${newLandCount || 0}`);
      console.log('C3: Calculation Failure (Area is null/NaN)');
      console.log('C3');
      return;
    }

    // Print concise evidence
    console.log(`Using JRC yearly classification year: ${usedYear}`);
    console.log(`Baseline water pixels in AOI (1km): ${baseCount}`);
    console.log(`New land pixels (1km): ${newLandCount || 0}`);
    console.log(`New land area (ha): ${areaHa.toFixed(1)}`);

    // Threshold: 800 ha
    const answer = areaHa > 800 ? 'A: Yes' : 'B: No';
    console.log(answer);
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
